// SplashPropOverride_StartEnd_FirstLoad.tsx
import * as React from "react"
import { Override } from "framer"

/**
 * Chỉ chạy lần đầu:
 * - Nếu sessionStorage.hasVisited === "true" -> giữ variant "end" (không animate)
 * - Nếu chưa -> chờ page load + minDuration -> animate scale/rotate/fadeout -> rồi set variant "end"
 */

type Options = {
    minDuration?: number
    scaleDurationMs?: number
    visitedKey?: string
    variantFrom?: string
    variantTo?: string
}

export function SplashPropOverride_StartEnd_FirstLoad(
    options?: Options
): Override {
    const {
        minDuration = 1200,
        scaleDurationMs = 900,
        visitedKey = "hasVisited",
        variantFrom = "start",
        variantTo = "end",
    } = options || {}

    const [ready, setReady] = React.useState<boolean>(false)
    const [scaling, setScaling] = React.useState<boolean>(false)
    const [visitedKnown, setVisitedKnown] = React.useState<boolean | null>(null)

    React.useEffect(() => {
        let cancelled = false

        try {
            const hasVisited = sessionStorage.getItem(visitedKey)
            if (hasVisited === "true") {
                setVisitedKnown(true)
                setReady(true)
                return
            } else {
                setVisitedKnown(false)
            }
        } catch (e) {
            setVisitedKnown(false)
        }

        const pageLoad = new Promise((res) => {
            if (typeof document === "undefined") return res(true)
            if (document.readyState === "complete") return res(true)
            window.addEventListener("load", () => res(true), { once: true })
            setTimeout(() => res(true), 800)
        })

        const minDelay = new Promise((res) =>
            setTimeout(res, Math.max(0, minDuration))
        )

        Promise.all([pageLoad, minDelay]).then(() => {
            if (cancelled) return

            setScaling(true)

            const t = setTimeout(() => {
                if (cancelled) return
                setScaling(false)
                setReady(true)
                try {
                    sessionStorage.setItem(visitedKey, "true")
                } catch (e) {}
            }, scaleDurationMs)

            return () => clearTimeout(t)
        })

        return () => {
            cancelled = true
        }
    }, [minDuration, scaleDurationMs, visitedKey])

    if (visitedKnown === true) {
        return {
            variant: variantTo,
        }
    }

    if (visitedKnown === null) {
        return {
            variant: variantFrom,
        }
    }

    return {
        variant: ready ? variantTo : variantFrom,

        animate: {
            scale: scaling ? 4 : 1,
            rotate: scaling ? 30 : 0,
            opacity: scaling ? 0 : 1,
        },

        transition: {
            duration: scaleDurationMs / 1000,
            ease: "easeInOut",
        },
    }
}
